/// One structured scene-to-2D-physics transform projection failure.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PhysicsDiagnostic2d {
    /// Runtime entity whose resolved hierarchy cannot be represented in 2D.
    pub entity: Entity,
    /// Engine-owned planar projection failure.
    pub error: PlanarPoseError,
}

/// Dedicated Native 2D runtime world and fixed-step outputs.
#[derive(Debug, Default)]
pub struct PhysicsRuntime2d {
    world: PhysicsWorld2d,
    contacts: Vec<ContactEvent2d>,
    diagnostics: Vec<PhysicsDiagnostic2d>,
}

impl PhysicsRuntime2d {
    /// Returns the dedicated 2D collision/query world. The 3D world is never consulted.
    pub fn world(&self) -> &PhysicsWorld2d {
        &self.world
    }

    /// Returns contact/trigger transitions emitted by the most recent fixed step.
    pub fn contacts(&self) -> &[ContactEvent2d] {
        &self.contacts
    }

    /// Returns structured hierarchy projection diagnostics from the most recent fixed step.
    pub fn diagnostics(&self) -> &[PhysicsDiagnostic2d] {
        &self.diagnostics
    }
}

fn physics_entity_key_2d(entity: Entity) -> u64 {
    (u64::from(entity.generation()) << 32) | u64::from(entity.id())
}

/// Synchronizes ECS-authored 2D bodies with the dedicated world, steps it, and writes dynamic poses back to local Transform.
pub fn physics_2d_fixed_system(
    fixed_time: Res<FixedTime>,
    settings: Res<PhysicsSettings2d>,
    mut runtime: ResMut<PhysicsRuntime2d>,
    globals: Query<&GlobalTransform>,
    mut bodies: Query<(
        &mut Transform,
        &GlobalTransform,
        Option<&Parent>,
        &mut RigidBody2d,
        &Collider2d,
    )>,
) {
    let global_matrices: HashMap<Entity, Mat4> = globals
        .iter()
        .map(|(entity, global)| (entity, global.matrix()))
        .collect();
    let mut active = BTreeSet::new();
    runtime.diagnostics.clear();

    for (entity, (_, global, _, body, collider)) in &mut bodies {
        let key = physics_entity_key_2d(entity);
        let authored_pose = match project_planar_transform(global.matrix()) {
            Ok(pose) => pose,
            Err(error) => {
                runtime.world.remove(key);
                runtime.diagnostics.push(PhysicsDiagnostic2d { entity, error });
                continue;
            }
        };
        active.insert(key);
        let pose = if body.mode == RigidBodyMode2d::Dynamic {
            runtime.world.body(key).map_or(authored_pose, |entry| entry.pose)
        } else {
            authored_pose
        };
        runtime.world.upsert(BodyEntry2d {
            entity: key,
            pose,
            body: **body,
            collider: collider.clone(),
        });
    }
    runtime.world.retain_entities(&active);
    runtime.contacts = runtime
        .world
        .step(fixed_time.fixed_delta.max(0.0), settings.gravity);

    for (entity, (transform, global, parent, body, _)) in &mut bodies {
        if body.mode != RigidBodyMode2d::Dynamic {
            continue;
        }
        let key = physics_entity_key_2d(entity);
        let Some(entry) = runtime.world.body(key) else {
            continue;
        };
        let (_, _, current_world_translation) = global.matrix().to_scale_rotation_translation();
        let desired_world = Mat4::from_scale_rotation_translation(
            Vec3::new(entry.pose.scale.x, entry.pose.scale.y, 1.0),
            Quat::from_rotation_z(entry.pose.rotation),
            Vec3::new(
                entry.pose.translation.x,
                entry.pose.translation.y,
                current_world_translation.z,
            ),
        );
        let local = parent
            .and_then(|parent| global_matrices.get(&parent.0).copied())
            .map_or(desired_world, |parent_world| parent_world.inverse() * desired_world);
        if !local.is_finite() {
            continue;
        }
        let (scale, rotation, translation) = local.to_scale_rotation_translation();
        transform.translation = translation;
        transform.rotation = rotation;
        transform.scale = scale;
        body.velocity = entry.body.velocity;
        body.angular_velocity = entry.body.angular_velocity;
    }
}

